%[text] Plot H3PO4
fname= 'titration_data.xlsx';
M = readmatrix(fname, 'Sheet', 'H3PO4 Titration', 'Range', 'D3:E41');
volp = M(:,1);
pHp = M(:,2);
plot(volp, pHp, '-o', 'Color', [0,0,0], 'MarkerFaceColor', [1,1,1], 'MarkerSize', 4); %[output:977c6032]
grid on; xlabel('Volume of NaOH (mL)'); ylabel('pH'); %[output:977c6032]
title('Titration Curve of H_3PO_4 with NaOH'); %[output:977c6032]
%[text] Plot Unknown Sample
M = readmatrix(fname, 'Sheet', 'Mystery Solution', 'Range', 'D3:E56');
volu = M(:,1);
pHu = M(:,2);
plot(volu, pHu, '-o', 'Color', [0,0,0], 'MarkerFaceColor', [1,1,1], 'MarkerSize', 4); %[output:1eea395c]
grid on; xlabel('Volume of NaOH (mL)'); ylabel('pH'); %[output:1eea395c]
xlim([0 12]);  %[output:1eea395c]
title('Titration Curve of Unknown Sample with NaOH'); %[output:1eea395c]
%[text] Equivalent Point of H3PO4
vavgeq1 = (volp(1:19) + volp(2:20)) ./2;
dvp= diff(volp(1:20));
dpHp= diff(pHp(1:20));
dpHpdvp= dpHp ./ dvp;
[~, imax] = max(dpHpdvp);
eq1= vavgeq1(imax) %[output:7058bc9e]
pHeq1 = interp1(volp,pHp,eq1) %[output:37871571]

vavgeq2 = (volp(20:end-1) + volp(21:end)) ./2;
dvp= diff(volp(20:end));
dpHp= diff(pHp(20:end));
dpHpdvp= dpHp ./ dvp;
[~, imax] = max(dpHpdvp);
eq2= vavgeq2(imax) %[output:7ec7e249]
pHeq2 = interp1(volp,pHp,eq2) %[output:04ea1010]
%[text] Equivalent Points of Unknown Solution
vavgEq = (volu(1:20) + volu(2:21)) ./ 2;
dpHdv = diff(pHu(1:21)) ./ diff(volu(1:21));
[~, imax] = max(dpHdv);
eq1Unknown = vavgEq(imax) %[output:32899873]
pHeq1u = interp1(volu,pHu,eq1Unknown) %[output:08a7b298]

vavgEq = (volu(21:end-1) + volu(22:end)) ./ 2;
dpHdv = diff(pHu(21:end)) ./ diff(volu(21:end));
[~, imax] = max(dpHdv);
eq2Unknown = vavgEq(imax) %[output:83e4988f]
pHeq2u = interp1(volu,pHu,eq2Unknown) %[output:557a7c67]
%[text] Marked Plots
plot(volp, pHp, '-','Color',[0,0,0]); %[output:28992644]
hold on %[output:28992644]
plot (eq2,pHeq2,'-o','Color', [0,0,0], 'MarkerFaceColor', [1,0,0], 'MarkerSize', 4); %[output:28992644]
plot ((eq2+eq1)/2,interp1(volp,pHp,(eq2+eq1)/2),'-o','Color', [0,0,0], 'MarkerFaceColor', [0,0,1], 'MarkerSize', 4); %[output:28992644]
plot (eq1,pHeq1,'-o','Color', [0,0,0], 'MarkerFaceColor', [1,0,0], 'MarkerSize', 4); %[output:28992644]
plot ((eq1/2),interp1(volp,pHp,(eq1/2)),'-o','Color', [0,0,0], 'MarkerFaceColor', [0,0,1], 'MarkerSize', 4); %[output:28992644]
plot (25,11.6,'-o','Color', [0,0,0], 'MarkerFaceColor', [0,0,1], 'MarkerSize', 4); %[output:28992644]
hold off %[output:28992644]
grid on; xlabel('Volume of NaOH (mL)'); ylabel('pH'); %[output:28992644]
title('Titration Curve of H_3PO_4 with NaOH'); %[output:28992644]

plot (volu,pHu,'-', 'Color',[0,0,0]) %[output:200d8fd2]
hold on %[output:200d8fd2]
plot (eq1Unknown,pHeq1u,'-o','Color', [0,0,0], 'MarkerFaceColor', [1,0,0], 'MarkerSize', 4); %[output:200d8fd2]
plot (eq2Unknown,pHeq2u,'-o','Color', [0,0,0], 'MarkerFaceColor', [1,0,0], 'MarkerSize', 4); %[output:200d8fd2]
hold off %[output:200d8fd2]
grid on; xlabel('Volume of NaOH (mL)'); ylabel('pH'); %[output:200d8fd2]
xlim([0 12]); %[output:200d8fd2]
title('Titration Curve of Unknown Sample with NaOH'); %[output:200d8fd2]

